"""Derive the local-feature development decision from captured results/audits."""
import json
from pathlib import Path
import statistics
import sys

directory, output = Path(sys.argv[1]), Path(sys.argv[2])
read = lambda name: json.loads((directory / name).read_text(encoding='utf8'))
p = read('protocol.json')
r, physical, numeric = [read('development/' + name) for name in ['results.json', 'physical-audit.json', 'numeric-audit.json']]
assert physical['passed'] and numeric['passed'] and not numeric['warnings']
rows = [read(f"development/rows/{h['seed']}.json") for h in p['developmentHistories']]
required = [c for c in r['comparisons'] if not c['optional']]
confirmation_exists = (directory / 'confirmation').exists()
if not r['promising']:
    assert not confirmation_exists
portability = read('supplemental/portability-resolution.json')
lines = ['# Local tile-coded SARSA: development result', '',
         f"The fixed new hypothesis **{'cleared' if r['promising'] else 'failed'} its prespecified development screen**. {sum(c['developmentalPositive'] for c in required)} of {len(required)} required contrast means were positive; {sum(v['passed'] for v in r['survival'])} of {len(r['survival'])} survival guards passed. Development never supplies qualification. Confirmation output exists: **{confirmation_exists}**. The earlier intervention and linear SARSA qualification remain failed; no RSI result or policy promotion is claimed.", '',
         'The user-directed research goal remains active. [The prospective design](LOCAL_TILE_DEVELOPMENT.md) and [frozen protocol](../evidence/sarsa-screen/20261024-local-tiles-development-v1/protocol.json) specify one representation hypothesis, not a candidate library or a post-result tuning round.', '',
         f"Eight fresh histories supplied {physical['mainWorlds']} main worlds and {physical['probes']} frozen probes ({physical['mainWorlds'] + physical['probes']} total). Sixteen distinct confirmation histories were reserved before outcomes. The combined development/conditional-confirmation cap is {p['budget']['totalWorlds']} worlds / {p['budget']['totalCollectionWorldSteps']:,} world steps. The failure rule bars confirmation, parameter tuning, reselection and sample extension on this bank.", '',
         'Each contrast below is an energy effect per original founder. Development uses positive means as a go/no-go screen; displayed bounds and exact paired sign-flip probabilities are descriptive here. They do not reclassify this bank as confirmation. The frozen confirmatory rule requires positive simultaneous lower bounds and p≤.05/12 on a separate bank.', '']
for c in r['comparisons']:
    lines.append(f"- `{c['id']}`: mean {c['mean']:.6f}, simultaneous lower {c['simultaneousLower']:.6f}, p={c['pOneSided']:.8g}; mean **{'positive' if c['developmentalPositive'] else 'not positive'}**{' (optional trace attribution)' if c['optional'] else ''}.")
lines += ['', 'Survival differences are candidate minus control, in percentage points. These observed-mean guards and descriptive intervals do not establish a survival benefit or noninferiority:', '']
for v in r['survival']:
    lo, hi = v['descriptiveCi95']
    lines.append(f"- {v['control']}: {100*v['mean']:.6f}, descriptive 95% interval [{100*lo:.6f}, {100*hi:.6f}]; **{'pass' if v['passed'] else 'fail'}**.")
lines += ['', 'Observed whole-sequence energy change per founder, and actual incurred external model charges per founder:', '']
for name in p['arms'] + ['linear', 'reflex']:
    endpoint = lambda row: row['programs']['linear']['arms']['candidate']['endpoint'] if name == 'linear' else row['reflex']['endpoint'] if name == 'reflex' else row['programs']['tile']['arms'][name]['endpoint']
    endpoints = [endpoint(row) for row in rows]
    lines.append(f"- {name}: net energy {statistics.mean(e['budgetAdjustedEnergyPerFounder'] for e in endpoints):.6f}; incurred external charge {statistics.mean(e['incurredEnergy']/e['founders'] for e in endpoints):.6f}; survivors {sum(e['survivors'] for e in endpoints)}/192.")
lines += ['', 'Charges affected live energy, rewards and trajectories. Adding them back would not measure a zero-price counterfactual. Legacy native controller prices remain separate from these external-program charges. The fixed feeding reflex is a human reference, not a learned policy.', '', 'The previous linear candidate supplies a separately recorded developmental reference:', '']
for c in r['linearReferenceComparisons']:
    lines.append(f"- `{c['id']}`: mean {c['mean']:.6f}.")
lines += ['', 'These linear means are diagnostic comparisons on fresh development data, not a new qualification result. Their shared incumbent/constant physical rows are identified explicitly; tile frozen/reset arms are not presented as matched linear ablations.', '',
          f"The full physical audit cold-replayed every registered development world, probe, state/checkpoint hash, factual trace and score. Independent Python reconstructed {numeric['factualTransitions']:,} factual transitions, {numeric['decisions']:,} learned-policy decisions and {numeric['reflexDecisions']:,} fixed-reflex decisions across {numeric['learnerBodies']:,} learner bodies, then checked all twelve contrasts and the decision rule. It passed with {len(numeric['warnings'])} warnings. The checker separately implements sparse feature quantization/hashing/collisions, normalization, action RNG, traces, reservoir and replay arithmetic; it does not import JavaScript scoring.", '',
          f"Collection wall time totaled {sum(row['runtime']['wallSeconds'] for row in rows):.6f} measured seconds, including evaluator recording/checkpoint overhead. Original failed-bank seeds and all reserved new world/resource/probe seeds are disjoint. The captured graph includes {len(p['sourceSha256'])} source files, {len(p['seedRegistries'])} prior registries and {len(p['engineeringSources'])} engineering-test sources. The default linear implementation still exactly matches the original captured experiment on the declared engineering seed; this is code compatibility, not cross-platform proof.", '',
          'A separate historical intervention portability check was also attempted without changing original bytes. The original strict auditor stopped on Windows/Node 22 at its first recorded development world. An independently captured diagnostic compared that same world under Windows Node 22.19.0 and the recorded Node 26.5.0 version, downloaded from the official distribution and SHA-256 verified. Both Windows runtimes produced byte-identical regenerated row files, but neither exactly matched the Mac-recorded row.', '',
          f"That one world contains {portability['firstWorld']['cases']} scheduled cases / {portability['firstWorld']['forkWorldSteps']:,} fork steps. Across {portability['node22']['counts']['numbersCompared']:,} numeric fields, {portability['node22']['counts']['numericDifferences']} differed, with maximum absolute difference {portability['node22']['maximumAbsoluteDifference']:.12g}; {portability['node22']['counts']['hashDifferences']} hashes differed. All natural choices matched in this one world. The maximum difference among its {portability['outcomeEnergyValuesCompared']} energy outcomes was {portability['maximumOutcomeEnergyDifference']:.12g}. These are descriptive differences, not a substituted tolerance or a whole-bank agreement claim. Matching Node versions did not resolve the discrepancy; the exact cross-platform cause remains unestablished. The original strict Windows audit remains failed and its log, both regenerated rows, source and checksum provenance are preserved. The original numerical audit of recorded data remains distinct from physical portability.", '',
          'The complete new raw bank, reserved seed identities, original frozen source graph, exclusion inputs, numerical/physical audits and portability artifacts travel in an additional checked archive. No earlier archive is rewritten. The prior study source/report text remains historical context, and these new findings amend the current interpretation rather than editing a recorded result.', '',
          'The next research action must address why continuing updates fail to establish new B/C skill and incumbent superiority. Nonlinear local features alone did not clear even the developmental screen. This does not prove every nonlinear representation or Expected SARSA variant fails. The earlier [32-seed neural/episodic factorial](NEURAL_MEMORY_INTERACTION.md) already failed to support a remaining-neural-output interference explanation; it must not be repeated unchanged or presented as a new cause. The open mechanisms are temporal-credit/bootstrapped-target quality and interference during actual continuing learning, under the same embodied obligations. Any credit-target revision must use only matured own factual experience and a new prospective bank. If control scope is later broadened, all acquired components must be explicitly owned, priced, checkpointed, frozen/reset and probed; simply enabling background acquisition would invalidate the controls. These are unresolved hypotheses, not a selected winning algorithm.', '',
          'Qualified continuing embodied learning and retained skills remain unachieved. Persistent autonomous algorithm revisions, acquired-state migration, copied-improvement controls and causal subsequent search-productivity gains are still required. The program registry is engineering groundwork, not evidence of any such revision or RSI.', '']
with output.open('x', encoding='utf8', newline='\n') as f:
    f.write('\n'.join(lines))
print(json.dumps({'report': str(output), 'developmentPromising': r['promising'], 'requiredPositiveMeans': sum(c['developmentalPositive'] for c in required), 'confirmationExists': confirmation_exists}))
